size_t max_iterations = 64;
void *key = const_cast<void*>(argkey);
void *data = const_cast<void*>(argdata);
void *evicted_key, *evicted_data;
size_t bucket = argbucket;
size_t alt_bucket;
size_t hash1, hash2;
size_t iteration = 0;

while (iteration < max_iterations) {
    if (ckh_insert(ckh, bucket, key, data)) {
        return false;
    }

    if (!ckh_lookup(ckh, bucket, &evicted_key, &evicted_data)) {
        return true;
    }

    ckh_remove(ckh, bucket, evicted_key, evicted_data);

    hash1 = ckh_hash(evicted_key, ckh->hash_seed);
    hash2 = ckh_hash2(hash1, ckh->hash_seed);
    alt_bucket = (hash2 % ckh->nbuckets);

    key = evicted_key;
    data = evicted_data;
    bucket = alt_bucket;
    iteration++;
}

return true;

